blosc/blosc2.c:2426:      fprintf(stderr, "blosc_getitem does not support lazy chunks.  Use blosc2_getitem_ctx instead.");
blosc/blosc2.c:2432:  result = _blosc_getitem(&context, src, INT32_MAX, start, nitems, dest);
blosc/blosc2.c:2454:  result = _blosc_getitem(context, src, srcsize, start, nitems, dest);
blosc/frame.c:1300:  int rc = blosc_getitem(coffsets, nchunk, 1, &offset);
blosc/frame.c:1584://  int rc2 = blosc_getitem(off_chunk, nchunks, 1, &offset);
